final class LoadErrorExceptionInvalidConfig extends LoadErrorException {
  const LoadErrorExceptionInvalidConfig({
    required this.field,
    required this.value,
    required this.reason,
    required this.detail,
  });
  final String field;
  final String value;
  final String reason;
