LoadErrorException _uniffiLiftLoadErrorException(Uint8List bytes) {
  final LoadError value = _uniffiDecodeLoadError(bytes);
  if (value is LoadErrorKindMismatch) {
    return LoadErrorExceptionKindMismatch(
      expected: value.expected,
      actual: value.actual,
      architecture: value.architecture,
    );
  }
  if (value is LoadErrorUnsupportedArchitecture) {
    return LoadErrorExceptionUnsupportedArchitecture(
      architecture: value.architecture,
    );
  }
  if (value is LoadErrorUnsupportedInferenceType) {
    return LoadErrorExceptionUnsupportedInferenceType(
      inferenceType: value.inferenceType,
    );
  }
  if (value is LoadErrorSource) {
    return LoadErrorExceptionSource(
      sourceKind: value.sourceKind,
      detail: value.detail,
    );
  }
  if (value is LoadErrorAssembly) {
    return LoadErrorExceptionAssembly(
      backend: value.backend,
      detail: value.detail,
    );
  }
  if (value is LoadErrorInvalidConfig) {
    return LoadErrorExceptionInvalidConfig(
      field: value.field,
      value: value.value,
      reason: value.reason,
      detail: value.detail,
    );
  }
  if (value is LoadErrorEngine) {
    return LoadErrorExceptionEngine(
      detail: value.detail,
    );
  }
  if (value is LoadErrorConsumed) return const LoadErrorExceptionConsumed();
  throw StateError('Unknown LoadError error variant while lifting exception: $value');
}

String _encodeBackendPreference(BackendPreference value) {
  return switch (value) {
    BackendPreference.auto => 'auto',
    BackendPreference.cpu => 'cpu',
    BackendPreference.gpu => 'gpu',
    BackendPreference.metal => 'metal',
  };
}

BackendPreference _decodeBackendPreference(String raw) {
  return switch (raw) {
    'auto' => BackendPreference.auto,
    'cpu' => BackendPreference.cpu,
    'gpu' => BackendPreference.gpu,
    'metal' => BackendPreference.metal,
    _ => throw StateError('Unknown BackendPreference variant: $raw'),
  };
}

String _encodeFfiError(FfiError value) {
  if (value is FfiErrorUnsupportedModality) {
    return jsonEncode({
      'tag': 'unsupportedModality',
    });
  }
  if (value is FfiErrorUnsupportedInferenceType) {
    return jsonEncode({
      'tag': 'unsupportedInferenceType',
      'inferenceType': value.inferenceType,
    });
  }
  if (value is FfiErrorBusy) {
    return jsonEncode({
      'tag': 'busy',
    });
  }
  if (value is FfiErrorCancelled) {
    return jsonEncode({
      'tag': 'cancelled',
    });
  }
  if (value is FfiErrorContextOverflow) {
    return jsonEncode({
      'tag': 'contextOverflow',
      'maxSeqLen': value.maxSeqLen,
      'by': value.by,
    });
  }
  if (value is FfiErrorEmptyInput) {
    return jsonEncode({
      'tag': 'emptyInput',
    });
  }
  if (value is FfiErrorIo) {
    return jsonEncode({
      'tag': 'io',
      'detail': value.detail,
    });
  }
  if (value is FfiErrorBackend) {
    return jsonEncode({
      'tag': 'backend',
      'detail': value.detail,
    });
  }
  if (value is FfiErrorGrammarParse) {
    return jsonEncode({
      'tag': 'grammarParse',
      'detail': value.detail,
    });
  }
  if (value is FfiErrorInvalidToken) {
    return jsonEncode({
      'tag': 'invalidToken',
      'id': value.id,
      'vocabSize': value.vocabSize,
    });
  }
  if (value is FfiErrorLoraParse) {
    return jsonEncode({
      'tag': 'loraParse',
      'detail': value.detail,
    });
  }
  if (value is FfiErrorOutOfMemory) {
    return jsonEncode({
      'tag': 'outOfMemory',
      'requestedBytes': value.requestedBytes,
    });
  }
  if (value is FfiErrorKvCompressionConflict) {
    return jsonEncode({
      'tag': 'kvCompressionConflict',
      'configured': value.configured,
      'requested': value.requested,
    });
  }
  if (value is FfiErrorLoraUnsupportedByBackend) {
    return jsonEncode({
      'tag': 'loraUnsupportedByBackend',
      'detail': value.detail,
    });
  }
  if (value is FfiErrorChatValidation) {
    return jsonEncode({
      'tag': 'chatValidation',
      'error': ValidationErrorFfiCodec.encode(value.error),
    });
  }
  throw StateError('Unknown FfiError variant instance: $value');
}

FfiError _decodeFfiError(String raw) {
  final Map<String, dynamic> map = jsonDecode(raw) as Map<String, dynamic>;
