  if (value is FfiErrorExceptionUnsupportedModality) {
    return jsonEncode({
      'tag': 'unsupportedModality',
    });
  }
  if (value is FfiErrorExceptionUnsupportedInferenceType) {
    return jsonEncode({
      'tag': 'unsupportedInferenceType',
      'inferenceType': value.inferenceType,
    });
  }
  if (value is FfiErrorExceptionBusy) {
    return jsonEncode({
      'tag': 'busy',
    });
  }
  if (value is FfiErrorExceptionCancelled) {
    return jsonEncode({
      'tag': 'cancelled',
    });
  }
  if (value is FfiErrorExceptionContextOverflow) {
    return jsonEncode({
      'tag': 'contextOverflow',
      'maxSeqLen': value.maxSeqLen,
      'by': value.by,
    });
  }
  if (value is FfiErrorExceptionEmptyInput) {
    return jsonEncode({
      'tag': 'emptyInput',
    });
  }
  if (value is FfiErrorExceptionIo) {
    return jsonEncode({
      'tag': 'io',
      'detail': value.detail,
    });
  }
  if (value is FfiErrorExceptionBackend) {
    return jsonEncode({
      'tag': 'backend',
      'detail': value.detail,
    });
  }
  if (value is FfiErrorExceptionGrammarParse) {
    return jsonEncode({
      'tag': 'grammarParse',
      'detail': value.detail,
    });
  }
  if (value is FfiErrorExceptionInvalidToken) {
    return jsonEncode({
      'tag': 'invalidToken',
      'id': value.id,
      'vocabSize': value.vocabSize,
    });
  }
  if (value is FfiErrorExceptionLoraParse) {
    return jsonEncode({
      'tag': 'loraParse',
      'detail': value.detail,
    });
  }
  if (value is FfiErrorExceptionOutOfMemory) {
    return jsonEncode({
      'tag': 'outOfMemory',
      'requestedBytes': value.requestedBytes,
    });
  }
  if (value is FfiErrorExceptionKvCompressionConflict) {
    return jsonEncode({
      'tag': 'kvCompressionConflict',
      'configured': value.configured,
      'requested': value.requested,
    });
  }
  if (value is FfiErrorExceptionLoraUnsupportedByBackend) {
    return jsonEncode({
      'tag': 'loraUnsupportedByBackend',
      'detail': value.detail,
    });
  }
  if (value is FfiErrorExceptionChatValidation) {
    return jsonEncode({
      'tag': 'chatValidation',
      'error': ValidationErrorFfiCodec.encode(value.error),
    });
  }
  throw StateError('Unknown FfiErrorException exception instance: $value');
}

FfiErrorException _decodeFfiErrorException(Object? raw) {
  final Map<String, dynamic> map = raw is String ? (jsonDecode(raw) as Map<String, dynamic>) : (raw as Map<String, dynamic>);
  final String? tag = map['tag'] as String?;
  switch (tag) {
    case 'unsupportedModality':
      return const FfiErrorExceptionUnsupportedModality();
    case 'unsupportedInferenceType':
      return FfiErrorExceptionUnsupportedInferenceType(
        inferenceType: map['inferenceType'] as String,
      );
    case 'busy':
      return const FfiErrorExceptionBusy();
    case 'cancelled':
      return const FfiErrorExceptionCancelled();
    case 'contextOverflow':
      return FfiErrorExceptionContextOverflow(
        maxSeqLen: (map['maxSeqLen'] as num).toInt(),
        by: (map['by'] as num).toInt(),
      );
    case 'emptyInput':
      return const FfiErrorExceptionEmptyInput();
    case 'io':
      return FfiErrorExceptionIo(
        detail: map['detail'] as String,
      );
    case 'backend':
      return FfiErrorExceptionBackend(
        detail: map['detail'] as String,
      );
    case 'grammarParse':
      return FfiErrorExceptionGrammarParse(
        detail: map['detail'] as String,
      );
    case 'invalidToken':
      return FfiErrorExceptionInvalidToken(
        id: (map['id'] as num).toInt(),
        vocabSize: (map['vocabSize'] as num).toInt(),
      );
    case 'loraParse':
      return FfiErrorExceptionLoraParse(
        detail: map['detail'] as String,
      );
    case 'outOfMemory':
      return FfiErrorExceptionOutOfMemory(
        requestedBytes: (map['requestedBytes'] as num).toInt(),
      );
    case 'kvCompressionConflict':
      return FfiErrorExceptionKvCompressionConflict(
        configured: map['configured'] as String,
        requested: map['requested'] as String,
      );
    case 'loraUnsupportedByBackend':
      return FfiErrorExceptionLoraUnsupportedByBackend(
        detail: map['detail'] as String,
      );
    case 'chatValidation':
      return FfiErrorExceptionChatValidation(
        error: ValidationErrorFfiCodec.decode(map['error'] as String),
      );
    default:
      throw StateError('Unknown FfiErrorException exception tag: $tag');
  }
}

String _encodeLoadErrorException(LoadErrorException value) {
  if (value is LoadErrorExceptionKindMismatch) {
    return jsonEncode({
      'tag': 'kindMismatch',
      'expected': value.expected,
      'actual': value.actual,
      'architecture': value.architecture,
    });
  }
  if (value is LoadErrorExceptionUnsupportedArchitecture) {
    return jsonEncode({
      'tag': 'unsupportedArchitecture',
      'architecture': value.architecture,
    });
  }
  if (value is LoadErrorExceptionUnsupportedInferenceType) {
    return jsonEncode({
      'tag': 'unsupportedInferenceType',
      'inferenceType': value.inferenceType,
    });
  }
  if (value is LoadErrorExceptionSource) {
    return jsonEncode({
      'tag': 'source',
      'sourceKind': value.sourceKind,
      'detail': value.detail,
    });
  }
  if (value is LoadErrorExceptionAssembly) {
    return jsonEncode({
      'tag': 'assembly',
      'backend': value.backend,
      'detail': value.detail,
    });
  }
  if (value is LoadErrorExceptionInvalidConfig) {
    return jsonEncode({
      'tag': 'invalidConfig',
      'field': value.field,
      'value': value.value,
      'reason': value.reason,
      'detail': value.detail,
    });
  }
  if (value is LoadErrorExceptionEngine) {
    return jsonEncode({
      'tag': 'engine',
      'detail': value.detail,
    });
  }
  if (value is LoadErrorExceptionConsumed) {
    return jsonEncode({
      'tag': 'consumed',
    });
  }
  throw StateError('Unknown LoadErrorException exception instance: $value');
}

LoadErrorException _decodeLoadErrorException(Object? raw) {
  final Map<String, dynamic> map = raw is String ? (jsonDecode(raw) as Map<String, dynamic>) : (raw as Map<String, dynamic>);
  final String? tag = map['tag'] as String?;
  switch (tag) {
    case 'kindMismatch':
      return LoadErrorExceptionKindMismatch(
        expected: map['expected'] as String,
        actual: map['actual'] as String,
        architecture: map['architecture'] as String,
      );
    case 'unsupportedArchitecture':
      return LoadErrorExceptionUnsupportedArchitecture(
        architecture: map['architecture'] as String,
      );
    case 'unsupportedInferenceType':
      return LoadErrorExceptionUnsupportedInferenceType(
        inferenceType: map['inferenceType'] as String,
      );
    case 'source':
      return LoadErrorExceptionSource(
        sourceKind: map['sourceKind'] as String,
        detail: map['detail'] as String,
      );
    case 'assembly':
      return LoadErrorExceptionAssembly(
        backend: map['backend'] as String,
        detail: map['detail'] as String,
      );
    case 'invalidConfig':
      return LoadErrorExceptionInvalidConfig(
        field: map['field'] as String,
        value: map['value'] as String,
        reason: map['reason'] as String,
        detail: map['detail'] as String,
      );
    case 'engine':
      return LoadErrorExceptionEngine(
        detail: map['detail'] as String,
      );
    case 'consumed':
      return const LoadErrorExceptionConsumed();
    default:
      throw StateError('Unknown LoadErrorException exception tag: $tag');
  }
}

