  static final ffi.Pointer<_UniFfiRustCallStatus> _freeArgStatus = calloc<_UniFfiRustCallStatus>();

  static void _uniffiFreeArgBuffer(_UniFfiRustBuffer buf) {
    if (buf.data == ffi.nullptr && buf.len == 0 && buf.capacity == 0) {
      return;
